//! Deterministic fixture generation (addendum §10).
//!
//! `fixtures/small-repo` is committed. `fixtures/large-repo` is generated by
//! [`generate_large_repo`] (10k+ files, a 24-level deep tree, one directory
//! with more entries than a listing page, ignored directories) and its output
//! is git-ignored; `examples/generate_large_repo.rs` writes it on demand and
//! the integration tests generate it under `target/`.

use std::fs;
use std::io;
use std::path::{Path, PathBuf};

/// Bump when the layout changes so cached generations are refreshed.
pub const LARGE_REPO_LAYOUT_VERSION: u32 = 1;
/// Marker file written last; its content is the layout version.
pub const LARGE_REPO_MARKER: &str = ".gritty-fixture";

/// Directory with more entries than one listing page (`MAX_PAGE_SIZE`).
pub const BULK_DIRECTORY: &str = "bulk";
pub const BULK_ENTRIES: usize = 5_200;
/// Root of the deep chain `deep/level_01/.../level_24/leaf.rs`.
pub const DEEP_DIRECTORY: &str = "deep";
pub const DEEP_LEVELS: u32 = 24;
pub const SRC_MODULES: usize = 50;
pub const FILES_PER_MODULE: usize = 100;
pub const DOC_FILES: usize = 200;
pub const NODE_MODULES_PACKAGES: usize = 20;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct LargeRepoSummary {
    pub files: u64,
    pub directories: u64,
    pub max_depth: u32,
}

/// Names of the root entries the generator creates, sorted the way a listing
/// returns them (directories first, then by name).
pub const LARGE_REPO_ROOT_ENTRIES: &[&str] = &[
    ".git",
    "bulk",
    "deep",
    "dist",
    "docs",
    "node_modules",
    "src",
    "target",
    ".gritty-fixture",
    "Cargo.toml",
    "README.md",
    "package.json",
];

/// (Re)generate the large fixture at `dir`. The directory is removed first.
pub fn generate_large_repo(dir: &Path) -> io::Result<LargeRepoSummary> {
    if dir.exists() {
        fs::remove_dir_all(dir)?;
    }
    fs::create_dir_all(dir)?;
    // Write through the canonical base so a relative or `..`-containing `dir`
    // is resolved once, and so the deep chain (which exceeds the legacy Windows
    // MAX_PATH in most checkouts) is created through a verbatim-prefixed path.
    let base = fs::canonicalize(dir)?;
    let mut generator = Generator::new(&base)?;

    generator.file(
        "README.md",
        "# large-repo\n\nGenerated fixture; do not edit.\n",
    )?;
    generator.file(
        "package.json",
        "{ \"name\": \"large-repo\", \"private\": true }\n",
    )?;
    generator.file("Cargo.toml", "[package]\nname = \"large-repo\"\n")?;

    generator.dir("src")?;
    for module in 0..SRC_MODULES {
        let dir = format!("src/module_{module:02}");
        generator.dir(&dir)?;
        for file in 0..FILES_PER_MODULE {
            generator.file(
                &format!("{dir}/file_{file:03}.ts"),
                "export const value = 1;\n",
            )?;
        }
    }
    generator.dir("docs")?;
    for doc in 0..DOC_FILES {
        generator.file(&format!("docs/guide_{doc:03}.md"), "# guide\n")?;
    }
    generator.dir(BULK_DIRECTORY)?;
    for entry in 0..BULK_ENTRIES {
        generator.file(&format!("{BULK_DIRECTORY}/entry_{entry:04}.txt"), "bulk\n")?;
    }
    let mut deep = PathBuf::from(DEEP_DIRECTORY);
    generator.dir(DEEP_DIRECTORY)?;
    for level in 1..=DEEP_LEVELS {
        deep.push(format!("level_{level:02}"));
        generator.dir(&deep.to_string_lossy())?;
        generator.file(&format!("{}/note.md", deep.to_string_lossy()), "deep\n")?;
    }
    generator.file(
        &format!("{}/leaf.rs", deep.to_string_lossy()),
        "fn leaf() {}\n",
    )?;
    generator.dir("node_modules")?;
    for package in 0..NODE_MODULES_PACKAGES {
        let dir = format!("node_modules/pkg_{package:02}");
        generator.dir(&dir)?;
        generator.file(&format!("{dir}/package.json"), "{}\n")?;
        generator.file(&format!("{dir}/index.js"), "module.exports = {};\n")?;
    }
    generator.dir("target")?;
    generator.dir("target/debug")?;
    for object in 0..20 {
        generator.file(&format!("target/debug/build_{object:02}.o"), "OBJ\n")?;
    }
    generator.dir("dist")?;
    for bundle in 0..10 {
        generator.file(&format!("dist/bundle_{bundle}.js"), "!function(){}();\n")?;
    }
    generator.dir(".git")?;
    generator.file(".git/HEAD", "ref: refs/heads/main\n")?;
    generator.file(".git/config", "[core]\n\tbare = false\n")?;

    generator.file(LARGE_REPO_MARKER, &LARGE_REPO_LAYOUT_VERSION.to_string())?;
    Ok(generator.summary(DEEP_LEVELS + 1))
}

/// `true` when `dir` holds a complete generation of the current layout.
pub fn large_repo_is_current(dir: &Path) -> bool {
    fs::read_to_string(dir.join(LARGE_REPO_MARKER))
        .is_ok_and(|content| content.trim() == LARGE_REPO_LAYOUT_VERSION.to_string())
}

struct Generator<'a> {
    root: &'a Path,
    files: u64,
    directories: u64,
}

impl<'a> Generator<'a> {
    fn new(root: &'a Path) -> io::Result<Self> {
        fs::create_dir_all(root)?;
        Ok(Self {
            root,
            files: 0,
            directories: 0,
        })
    }

    fn dir(&mut self, relative: &str) -> io::Result<()> {
        fs::create_dir(self.root.join(relative))?;
        self.directories += 1;
        Ok(())
    }

    fn file(&mut self, relative: &str, content: &str) -> io::Result<()> {
        fs::write(self.root.join(relative), content)?;
        self.files += 1;
        Ok(())
    }

    fn summary(&self, max_depth: u32) -> LargeRepoSummary {
        LargeRepoSummary {
            files: self.files,
            directories: self.directories,
            max_depth,
        }
    }
}
